var e={"term.setting":`Modo código`,"term.settingDesc":`Para trabajar en código con Claude: una copia separada por sesión (su propia rama y carpeta, que termina con una pull request que Claude escribe y vigila) y un terminal bajo la conversación (Ctrl+J, /terminal) abierto en los repositorios git de la sesión. Los cambios de cada respuesta (diff, commit, push, pull request) y la vista de pull requests se muestran sin él. Nunca para agentes. Pide tu contraseña para activarlo.`,"term.enableTitle":`Activar el modo código`,"term.enableDesc":`El modo código añade un terminal, que ejecuta cualquier comando en este servidor con sus permisos, y copias separadas de un repositorio para las sesiones. Escribe tu contraseña para confirmar.`,"term.password":`Contraseña`,"term.badPassword":`Contraseña incorrecta`,"term.enable":`Activar`,"term.openFailed":`El terminal no se abrió`,"term.tooMany":`Hay 4 terminales abiertos: cierra uno primero`,"term.close":`Cerrar este terminal`,"term.new":`Nuevo terminal`,"term.quote":`Enviar la selección a Claude`,"term.openCount":`{count} abiertos`,"term.openCount#one":`{count} abierto`,"term.closeAll":`Cerrar todo`,"term.hide":`Ocultar el terminal`,"term.opening":`Abriendo…`,"term.ended":`[terminal finalizado]`,"term.topicFolder":`Carpeta del tema`};export{e as default};